"""Main entry point for BGP Monitor application.""" import sys import signal import tkinter as tk import logging import logging.handlers import json # Import json for formatter from utils.config_manager import config_manager # Import shared config manager from gui.main_window import BGPMonitorGUI
def signal_handler(signum, frame): """Handle interrupt signals.""" sys.exit(0)
class JsonSyslogFormatter(logging.Formatter): """ Custom formatter to output log records as JSON, including extra fields relevant for SIEM. """ def format(self, record): log_entry = { 'timestamp': self.formatTime(record, self.datefmt), 'name': record.name, 'level': record.levelname, 'message': record.getMessage(), } # Add standard exception info if present if record.exc_info: log_entry['exception'] = self.formatException(record.exc_info) if record.stack_info: log_entry['stack_info'] = self.formatStack(record.stack_info)
# Add extra fields passed via logger.log(..., extra=...) # Filter out standard fields already included standard_fields = {'args', 'asctime', 'created', 'exc_info', 'exc_text', 'filename', 'funcName', 'levelname', 'levelno', 'lineno', 'module', 'msecs', 'message', 'msg', 'name', 'pathname', 'process', 'processName', 'relativeCreated', 'stack_info', 'thread', 'threadName'} if hasattr(record, '__dict__'): extra_data = {k: v for k, v in record.__dict__.items() if k not in standard_fields} if extra_data: log_entry['extra'] = extra_data
return json.dumps(log_entry)
def setup_logging(): """Configure logging based on application settings.""" app_settings = config_manager.load_app_settings() log_settings = app_settings.get("logging", {}) log_level_str = log_settings.get("level", "INFO").upper() log_level = getattr(logging, log_level_str, logging.INFO)
# Basic configuration (console or file - adjust as needed) # Ensure handlers are removed before basicConfig to avoid duplicates if run multiple times root_logger = logging.getLogger() if root_logger.hasHandlers(): for handler in root_logger.handlers[:]: root_logger.removeHandler(handler)
log_format = '%(asctime)s - %(name)s - %(levelname)s - %(message)s' logging.basicConfig(level=log_level, format=log_format) # Basic config first
# Syslog configuration syslog_config = log_settings.get("syslog", {}) if syslog_config.get("enabled", False): host = syslog_config.get("host", "localhost") port = syslog_config.get("port", 514) protocol = syslog_config.get("protocol", "UDP").upper()
if protocol == "TCP": socktype = logging.handlers.socket.SOCK_STREAM else: # Default to UDP socktype = logging.handlers.socket.SOCK_DGRAM
try: syslog_handler = logging.handlers.SysLogHandler(address=(host, port), socktype=socktype) # Use the custom JSON formatter for Syslog formatter = JsonSyslogFormatter() syslog_handler.setFormatter(formatter)
# Add handler to root logger logging.getLogger().addHandler(syslog_handler) logging.info(f"Syslog handler configured for {host}:{port} ({protocol})") except Exception as e: logging.error(f"Failed to configure Syslog handler for {host}:{port} ({protocol}): {e}")
def main(): # --- Setup Logging First --- setup_logging() # --------------------------
# Set up signal handlers signal.signal(signal.SIGINT, signal_handler) signal.signal(signal.SIGTERM, signal_handler)
# Create and run GUI root = tk.Tk() app = BGPMonitorGUI(root) root.protocol("WM_DELETE_WINDOW", app.on_closing)
try: root.mainloop() except KeyboardInterrupt: app.on_closing() finally: # Ensure sys.exit is called even if mainloop raises other exceptions # Although KeyboardInterrupt is caught, other Tkinter errors might occur. logging.info("Application exiting.") sys.exit(0)
if __name__ == "__main__": main()

"""Manage WebSocket connections to RIPE RIS."""
import asyncio
import websockets
import json
import logging
from typing import Dict, Set, Optional, Callable, Any
from websockets.exceptions import WebSocketException, ConnectionClosed

class ConnectionManager:
    def __init__(self, message_callback: Callable[[Dict[str, Any]], None]):
        self.websocket = None
        self.message_callback = message_callback
        self.running = True
        self._listen_task = None
        self._event_loop = None
        self.RIPE_RIS_URL = 'wss://ris-live.ripe.net/v1/ws/'

    async def connect(self) -> bool:
        """Connect to RIPE RIS WebSocket."""
        try:
            self.websocket = await websockets.connect(self.RIPE_RIS_URL)
            logging.info("Connected to RIPE RIS WebSocket")
            return True
        except Exception as e:
            logging.error(f"Failed to connect to RIPE RIS: {e}")
            return False

    async def subscribe(self, collector=None) -> bool:
        """Subscribe to BGP updates."""
        if not self.websocket:
            return False

        try:
            subscription = {
                "type": "ris_subscribe",
                "data": {
                    "type": "UPDATE"  # Subscribe to all update messages
                }
            }

            # Add collector if specified
            if collector:
                subscription["data"]["host"] = collector

            await self.websocket.send(json.dumps(subscription))
            logging.info(f" Subscribed to BGP updates{' for ' + collector if collector else ''}")
            return True

        except Exception as e:
            logging.error(f" Failed to subscribe{' to ' + collector if collector else ''}: {e}")
            return False

    async def listen(self):
        """Listen for incoming messages."""
        self.running = True

        while self.running:
            try:
                # Check if websocket is closed or None
                if not self.websocket:
                    logging.info("WebSocket connection closed, stopping listen loop")
                    break

                # Receive message with timeout
                try:
                    message = await asyncio.wait_for(self.websocket.recv(), timeout=1.0)
                    if message:
                        # Debug log raw message
                        logging.debug(f"Raw message received: {message}")

                        # Parse message once here
                        try:
                            data = json.loads(message)
                            logging.debug(f"Parsed message structure:\n{json.dumps(data, indent=2)}")
                            if data.get("type") == "ris_message":
                                if self.message_callback:
                                    try:
                                        if asyncio.iscoroutinefunction(self.message_callback):
                                            await self.message_callback(data)
                                        else:
                                            self.message_callback(data)
                                    except Exception as e:
                                        logging.error(f"Error in message callback: {e}", exc_info=True)
                            elif data.get("type") == "ris_error":
                                logging.error(f"Received error: {data}")
                        except json.JSONDecodeError as e:
                            logging.error(f"Failed to parse message: {e}")
                            logging.debug(f"Raw message: {message}")
                except asyncio.TimeoutError:
                    # Timeout is normal, just continue
                    continue
                except Exception as e:
                    if not self.running:
                        # If we're stopping, this is expected
                        break
                    logging.error(f"Error in listen loop: {e}")
                    if "ConnectionClosed" in str(e):
                        break

            except Exception as e:
                if not self.running:
                    # If we're stopping, this is expected
                    break
                logging.error(f"Error in listen loop: {e}")
                # Break on connection errors
                if "ConnectionClosed" in str(e) or isinstance(e, AttributeError):
                    break
                # For other errors, wait a bit before retrying
                await asyncio.sleep(1)

        # Ensure we close the connection when the listen loop ends
        if self.websocket:
            await self.close()

        self.running = False
        logging.info("Listen loop stopped")

    async def close(self):
        """Close the WebSocket connection asynchronously."""
        if self.websocket:
            try:
                # Get all tasks in the current loop
                loop = asyncio.get_running_loop()
                tasks = [t for t in asyncio.all_tasks(loop) if t is not asyncio.current_task()]

                # Cancel all other tasks (including keepalive)
                for task in tasks:
                    task.cancel()
                    try:
                        await task
                    except asyncio.CancelledError:
                        pass

                # Now close the websocket
                await self.websocket.close()
                self.websocket = None
                logging.info("✓ WebSocket connection closed")
            except Exception as e:
                logging.error(f"Error during WebSocket close: {e}")
                self.websocket = None

    def stop(self):
        """Stop the WebSocket connection."""
        self.running = False

        # Cancel listen task if running
        if self._listen_task and not self._listen_task.done():
            self._listen_task.cancel()

        # Close WebSocket connection
        if self.websocket:
            try:
                # Try to get the current event loop
                try:
                    loop = asyncio.get_event_loop()
                except RuntimeError:
                    # If no loop exists, create a new one
                    loop = asyncio.new_event_loop()
                    asyncio.set_event_loop(loop)

                # Create a future for the close operation
                close_future = asyncio.run_coroutine_threadsafe(
                    self.close(),
                    loop
                )

                # Wait for the close operation to complete with timeout
                try:
                    close_future.result(timeout=5.0)
                except Exception as e:
                    logging.error(f"Error waiting for WebSocket close: {e}")
                    # Force close the websocket
                    self.websocket = None

            except Exception as e:
                logging.error(f"✗ Error closing WebSocket: {e}")
                # Force close the websocket if async close fails
                self.websocket = None

