try: # First, test basic connection with db_manager.driver.session() as session: result = session.run("RETURN 1 as test") test_value = result.single()["test"] print("✓ Basic connection test successful")
# Clear any existing test data print("\nClearing any existing test data...") session.run(""" MATCH (u:Update {is_test: true})-[r]->(p:Prefix) WHERE p.is_test = true DETACH DELETE u, p """) print("✓ Test data cleared")
# Test data test_data = { 'timestamp': datetime.datetime.now(), 'collector': 'test_collector', 'peer_asn': '12345', 'prefix': '192.168.0.0/24', 'as_path': '12345,67890', 'next_hop': '10.0.0.1', 'communities': ['100:200', '300:400'], 'is_test': True # Mark as test data }
