# Try to retrieve data print("\nRetrieving test data...") with db_manager.driver.session() as session: result = session.run(""" MATCH (u:Update {is_test: true})-[:AFFECTS]->(p:Prefix) WHERE u.collector = 'test_collector' RETURN u, p """) records = list(result) if records: print("✓ Successfully retrieved test data") update = records[0]['u'] prefix = records[0]['p'] print(f"\nRetrieved update details:") print(f"- Collector: {update['collector']}") print(f"- Peer ASN: {update['peer_asn']}") print(f"- AS Path: {update['as_path']}") print(f"- Prefix: {prefix['prefix']}") else: print("✗ No test data found")
print("\nConnection test completed successfully!")
except Exception as e: print(f"✗ Error during test: {str(e)}") import traceback print("\nFull traceback:") traceback.print_exc()
finally: print("\nCleaning up...") try: with db_manager.driver.session() as session: session.run(""" MATCH (u:Update {is_test: true})-[r]->(p:Prefix) WHERE p.is_test = true DETACH DELETE u, p """) print("✓ Test data cleaned up") except Exception as e: print(f"✗ Error during cleanup: {str(e)}")
db_manager.close() print("Connection closed")
