"""Test WebSocket connection to RIPE RIS Live service.""" import sys import json import asyncio import websockets from pathlib import Path from datetime import datetime
# Add project root to Python path project_root = Path(__file__).parent.parent sys.path.append(str(project_root))
def print_header(text): """Print a section header.""" print(f"\n{text}") print("=" * 50)
async def test_websocket(): """Test WebSocket connection and message reception.""" uri = "wss://ris-live.ripe.net/v1/ws/" messages_received = 0 valid_messages = 0 test_passed = False
try: print_header("Testing WebSocket Connection")
# Set connection timeout async with websockets.connect(uri, ping_interval=None, close_timeout=20) as websocket: # 1. Test Connection print("\n1. Testing Connection...") try: await websocket.ping() print("✓ Connection established") except Exception as e: print(f"✗ Connection failed: {str(e)}") return False
# 2. Send Subscription print("\n2. Sending Subscription...") subscription = { "type": "ris_subscribe", "data": { "host": "rrc01.ripe.net", "type": "UPDATE", "require": "announcements" } }
try: await websocket.send(json.dumps(subscription)) print("✓ Subscription sent") except Exception as e: print(f"✗ Subscription failed: {str(e)}") return False
# 3. Receive Messages print("\n3. Receiving Messages...") start_time = datetime.now()
try: for i in range(20): try: message = await asyncio.wait_for(websocket.recv(), timeout=5.0) messages_received += 1
data = json.loads(message) msg_data = data.get('data', {})
if (data.get('type') == 'ris_message' and msg_data.get('host') == 'rrc01.ripe.net'):
announcements = msg_data.get('announcements', []) peer_asn = msg_data.get('peer_asn')
if announcements and peer_asn: valid_messages += 1 status = "✓"
# Get the first announcement's path first_announcement = announcements[0] if announcements else {} prefix = first_announcement.get('prefix', 'Unknown') as_path = msg_data.get('path', []) # Path is at the message level
print(f"\n{status} Message {messages_received}:") print(f" Peer ASN: {peer_asn}") print(f" Prefix: {prefix}") print(f" AS Path: {','.join(map(str, as_path)) if as_path else 'No path'}") if len(announcements) > 1: print(f" Additional Announcements: {len(announcements)-1}") else: status = "!" print(f"\n{status} Message {messages_received}: No announcements") else: print(f"\n✗ Message {messages_received}: Invalid format")
except asyncio.TimeoutError: print(f"\n! Timeout waiting for message {i+1}") break except json.JSONDecodeError: print(f"\n✗ Message {messages_received}: Invalid JSON") except Exception as e: print(f"\n✗ Error processing message {messages_received}: {str(e)}")
except Exception as e: print(f"\n✗ Error receiving messages: {str(e)}")
# Calculate test results duration = (datetime.now() - start_time).total_seconds() test_passed = messages_received >= 15 and valid_messages >= 10
# Print Results print_header("Test Results") if test_passed: print("✓ Test PASSED") else: print("✗ Test FAILED")
print(f"\nStatistics:") print(f" Duration: {duration:.1f} seconds") print(f" Messages Received: {messages_received}/20") print(f" Valid Messages: {valid_messages}/{messages_received}") print(f" Messages/Second: {messages_received/duration:.1f}")
except websockets.exceptions.WebSocketException as e: print("\n✗ WebSocket Error:") print(f" {str(e)}") except Exception as e: print("\n✗ Unexpected Error:") print(f" {str(e)}") import traceback traceback.print_exc()
return test_passed
if __name__ == "__main__": asyncio.run(test_websocket())

"""Validate Neo4j data storage for BGP updates.""" import sys import argparse from pathlib import Path from datetime import datetime, timedelta
# Add project root to Python path project_root = Path(__file__).parent.parent sys.path.append(str(project_root))
from utils.db_manager import BGPDatabaseManager from config.database_config import NEO4J_CONFIG
def print_db_stats(session): """Print database statistics.""" print("\nDatabase Statistics and Analysis") print("=" * 50)
# Count by node type queries = [ ("Total Updates", "MATCH (u:Update) RETURN count(u) as count"), ("Total Prefixes", "MATCH (p:Prefix) RETURN count(p) as count"), ("Total Relationships", "MATCH (u:Update)-[r:AFFECTS]->(p:Prefix) RETURN count(r) as count"), ("Updates in last hour", """ MATCH (u:Update) WHERE datetime(toString(u.timestamp)) > datetime() - duration('PT1H') RETURN count(u) as count """), ("Updates in last 24h", """ MATCH (u:Update) WHERE datetime(toString(u.timestamp)) > datetime() - duration('P1D') RETURN count(u) as count """), ("Most Active Peer ASNs (Top 5)", """ MATCH (u:Update) WITH u.peer_asn as asn, count(u) as count ORDER BY count DESC LIMIT 5 RETURN asn, count """), ("Most Active Prefixes (Top 5)", """ MATCH (u:Update)-[:AFFECTS]->(p:Prefix) WITH p.prefix as prefix, count(u) as updates ORDER BY updates DESC LIMIT 5 RETURN prefix, updates """), ("Updates by Collector", """ MATCH (u:Update) WITH u.collector as collector, count(u) as count ORDER BY count DESC RETURN collector, count """), ("Recent Updates (Last 5)", """ MATCH (u:Update)-[:AFFECTS]->(p:Prefix) RETURN u.timestamp as time, u.collector as collector, u.peer_asn as peer_asn, p.prefix as prefix ORDER BY u.timestamp DESC LIMIT 5 """) ]
for description, query in queries: print(f"\n{description}:") try: result = session.run(query) records = list(result)
if description == "Recent Updates (Last 5)": for record in records: print(f" - Time: {record['time']}") print(f" Collector: {record['collector']}") print(f" Peer ASN: {record['peer_asn']}") print(f" Prefix: {record['prefix']}") print() elif description.endswith("(Top 5)"): if "Prefix" in description: for record in records: print(f" - Prefix: {record['prefix']}, Updates: {record['updates']}") else: for record in records: print(f" - ASN: {record['asn']}, Count: {record['count']}") elif "by" in description: for record in records: name = record['collector'] name = name if name else 'unknown' print(f" - {name}: {record['count']}") else: if records: print(f" {records[0]['count']}") except Exception as e: print(f" Error getting {description}: {str(e)}")
def run_connection_test(session): """Run a test to verify database connection and operations.""" print("\nRunning Database Connection Test") print("=" * 50)
try: # Clear any previous test data print("\n1. Clearing previous test data...") session.run(""" MATCH (u:Update {is_test: true})-[r]->(p:Prefix) WHERE p.is_test = true DETACH DELETE u, p """) print("✓ Previous test data cleared")
# Test storing a sample update print("\n2. Testing update storage...") test_update = { "timestamp": datetime.now(), "collector": "test-collector", "peer_asn": "12345", "prefix": "192.0.2.0/24", "as_path": "12345,23456", "next_hop": "192.0.2.1", "message_type": "announcement", "is_test": True }
# Store test update with test marker with session.begin_transaction() as tx: query = """ MERGE (p:Prefix {prefix: $prefix}) ON CREATE SET p.is_test = true WITH p CREATE (u:Update) SET u = $update_props CREATE (u)-[:AFFECTS]->(p) """ tx.run(query, prefix=test_update['prefix'], update_props={ 'timestamp': test_update['timestamp'], 'collector': test_update['collector'], 'peer_asn': test_update['peer_asn'], 'as_path': test_update['as_path'], 'next_hop': test_update['next_hop'], 'message_type': test_update['message_type'], 'is_test': True } ) tx.commit() print("✓ Test update stored successfully")
# Verify the stored test data print("\n3. Verifying stored test data...") query = """ MATCH (u:Update {is_test: true})-[:AFFECTS]->(p:Prefix) WHERE u.collector = 'test-collector' RETURN u, p """ result = session.run(query) records = list(result) if records: print("✓ Test data verified successfully") update = records[0]['u'] prefix = records[0]['p'] print("\nTest Update Details:") print(f"- Collector: {update['collector']}") print(f"- Peer ASN: {update['peer_asn']}") print(f"- AS Path: {update['as_path']}") print(f"- Prefix: {prefix['prefix']}") else: print("✗ No test data found")
# Clean up test data print("\n4. Cleaning up test data...") session.run(""" MATCH (u:Update {is_test: true})-[r]->(p:Prefix) WHERE p.is_test = true DETACH DELETE u, p """) print("✓ Test data cleaned up")
print("\nConnection Test Completed Successfully!")
except Exception as e: print(f"\n✗ Error during test: {str(e)}") print(f"Error type: {type(e).__name__}") if hasattr(e, 'message'): print(f"Error message: {e.message}") import traceback print("\nFull traceback:") traceback.print_exc()
def main(args=None): """Main function that can be called directly or via command line.""" if args is None: # When called from UI, create default arguments from argparse import Namespace args = Namespace() args.test = False # Don't just run test args.stats_only = False # Don't just show stats
db_manager = None try: print("\nConnecting to Neo4j database...") db_manager = BGPDatabaseManager(**NEO4J_CONFIG)
with db_manager.driver.session() as session: # Show statistics first print_db_stats(session)
# Then run the test unless stats_only is True if not args.stats_only: run_connection_test(session)
except Exception as e: print(f"\nError: {str(e)}") import traceback traceback.print_exc() finally: if db_manager: db_manager.close()
if __name__ == "__main__": parser = argparse.ArgumentParser(description='Validate Neo4j BGP data storage') parser.add_argument('--test', action='store_true', help='Run connection test') parser.add_argument('--stats-only', action='store_true', help='Show only database statistics') args = parser.parse_args() main(args)

