if __name__ == "__main__": test_connection()

"""Utility functions for BGP data processing."""
import re
import logging
from datetime import datetime
from pathlib import Path
import bz2 # For handling .bz2 compressed files from CAIDA

def validate_as_number(as_number):
    """Validate AS number format."""
    try:
        as_num = int(as_number)
        return 1 <= as_num <= 4294967295
    except ValueError:
        return False

def parse_as_path(as_path):
    """Parse AS path string into list of AS numbers."""
    if not as_path:
        return []
    return [int(asn) for asn in as_path.split(',') if asn.isdigit()]

def format_timestamp(timestamp):
    """Format timestamp for display."""
    try:
        if isinstance(timestamp, (int, float)):
            return datetime.fromtimestamp(timestamp).strftime('%Y-%m-%d %H:%M:%S')
        # Handle cases where timestamp might already be a datetime object
        elif isinstance(timestamp, datetime):
             return timestamp.strftime('%Y-%m-%d %H:%M:%S')
        # Fallback for other types or potential string formats
        return str(timestamp)
    except Exception:
        return str(timestamp)

def validate_prefix(prefix):
    """Validate IP prefix format."""
    ipv4_pattern = r'^(\d{1,3}\.){3}\d{1,3}/\d{1,2}$'
    ipv6_pattern = r'^([0-9a-fA-F:]+:+)+[0-9a-fA-F:/]+/\d{1,3}$' # Adjusted IPv6 pattern slightly
    try:
        # More robust validation using ipaddress module
        import ipaddress
        ipaddress.ip_network(prefix, strict=False)
        return True
    except ValueError:
        return False
    except ImportError:
        # Fallback to regex if ipaddress module is somehow unavailable
        return bool(re.match(ipv4_pattern, prefix) or re.match(ipv6_pattern, prefix))


def format_communities(communities):
    """Format BGP communities for display."""
    if not communities:
        return ""
    # Handle potential string representation of list
    if isinstance(communities, str):
        try:
            # Safely evaluate string literal to list
            import ast
            communities = ast.literal_eval(communities)
            if not isinstance(communities, list):
                 return str(communities) # Return original string if not a list after eval
        except (ValueError, SyntaxError):
             return communities # Return original string if eval fails

    # Format list of communities
    if isinstance(communities, list):
        return ', '.join(f"{c[0]}:{c[1]}" if isinstance(c, (list, tuple)) and len(c) == 2 else str(c)
                        for c in communities)
    # Fallback for unexpected types
    return str(communities)


# --- AS Relationship Data Handling ---

# Global dictionary to store relationships: {(asn1, asn2): relationship_code}
# Relationship codes (based on CAIDA format):
#  -1: Provider-to-Customer (p2c) (asn1 is provider, asn2 is customer)
#   0: Peer-to-Peer (p2p)
#   1: Customer-to-Provider (c2p) (asn1 is customer, asn2 is provider) - derived from p2c
#   2: Sibling-to-Sibling (s2s) - Often treated like p2p for valley-free
AS_RELATIONSHIPS = {}
P2C = -1
P2P = 0
C2P = 1
S2S = 2
UNKNOWN = 99

# --- AS Relationship Data Source ---
# The following functions rely on AS relationship data, typically sourced from CAIDA.
# Download the latest 'AS Relationships' dataset file (e.g., YYYYMMDD.as-rel.txt.bz2)
# from https://publicdata.caida.org/datasets/as-relationships/serial-1/
# and place it in the 'data/' directory, renaming it to 'as_relationships.txt.bz2'.
# Without this file, route leak detection based on valley-free paths will be limited.
# ---

# Default path for the relationship file
DEFAULT_AS_REL_FILE_PATH = Path(__file__).parent.parent / "data" / "as_relationships.txt.bz2"

def load_as_relationships(filepath=DEFAULT_AS_REL_FILE_PATH):
    """
    Load AS relationship data from a CAIDA formatted file (e.g., YYYYMMDD.as-rel.txt.bz2).
    Format expected: asn1|asn2|relationship_code (# comments allowed)
    """
    global AS_RELATIONSHIPS
    AS_RELATIONSHIPS = {} # Clear previous data
    logging.info(f"Attempting to load AS relationships from: {filepath}")

    if not filepath.exists():
        logging.warning(f"AS relationship file not found: {filepath}. Route leak detection will be basic.")
        # Add a dummy entry for testing framework
        # AS_RELATIONSHIPS[(174, 3356)] = P2P # Example: Cogent peer Level3
        # AS_RELATIONSHIPS[(3356, 12345)] = P2C # Example: Level3 provider to Customer 12345
        return False

    try:
        open_func = bz2.open if str(filepath).endswith(".bz2") else open
        with open_func(filepath, "rt", encoding="utf-8") as f:
            for line in f:
                # Skip comment lines
                if line.startswith('#'):
                    continue

                parts = line.strip().split('|')
                if len(parts) == 3:
                    try:
                        asn1 = int(parts[0])
                        asn2 = int(parts[1])
                        rel_code = int(parts[2])

                        # Store the relationship (p2c or p2p or s2s)
                        # We derive c2p during lookup if needed
                        if rel_code in [P2C, P2P, S2S]:
                             # Ensure lower ASN is first for consistent key lookup? Maybe not necessary.
                             # key = tuple(sorted((asn1, asn2))) # Alternative key style
                             key = (asn1, asn2)
                             AS_RELATIONSHIPS[key] = rel_code

                    except ValueError:
                        logging.warning(f"Skipping invalid line in AS relationship file: {line.strip()}")
                        continue
        logging.info(f"Successfully loaded {len(AS_RELATIONSHIPS)} AS relationships.")
        return True
    except Exception as e:
        logging.error(f"Error loading AS relationship file {filepath}: {e}")
        AS_RELATIONSHIPS = {} # Ensure it's empty on error
        return False

def get_as_relationship(asn1: int, asn2: int) -> int:
    """
    Get the relationship between two ASNs.
    Returns P2C, P2P, C2P, S2S, or UNKNOWN.
    """
    if not AS_RELATIONSHIPS:
        # logging.debug("AS relationship data not loaded.") # Too noisy
        return UNKNOWN

    # Check direct relationship (asn1 -> asn2)
    rel = AS_RELATIONSHIPS.get((asn1, asn2))
    if rel is not None:
        return rel

    # Check reverse relationship (asn2 -> asn1)
    reverse_rel = AS_RELATIONSHIPS.get((asn2, asn1))
    if reverse_rel is not None:
        # Invert the relationship code if found in reverse
        if reverse_rel == P2C:
            return C2P # If asn2 is provider to asn1, then asn1 is customer of asn2
        elif reverse_rel == P2P:
            return P2P
        elif reverse_rel == S2S:
             return S2S
        # C2P shouldn't be stored directly based on CAIDA format, but handle defensively
        elif reverse_rel == C2P:
             return P2C

    # logging.debug(f"No relationship found between AS{asn1} and AS{asn2}")
    return UNKNOWN

# --- End AS Relationship Data Handling ---

"""Data management utilities for BGP Monitor.""" import os import csv import shutil import tempfile import pandas as pd import json from datetime import datetime from pathlib import Path import logging
class DataManager: def __init__(self, base_dir="data"): """Initialize data manager with base directory.""" self.base_dir = Path(base_dir) self.current_file = None self.current_writer = None self.csv_file = None self.headers = [ 'timestamp', 'prefix', 'peer', 'peer_asn', 'path', 'next_hop', 'type', 'origin', 'aggregator', 'community', 'withdrawals', 'host', 'id', 'raw' ] self.ensure_data_directory()
def ensure_data_directory(self): """Create data directory if it doesn't exist.""" os.makedirs(self.base_dir, exist_ok=True)
def get_current_file_path(self): """Get the current file path based on timestamp.""" timestamp = datetime.now().strftime("%Y%m%d_%H%M") return self.base_dir / f"bgp_updates_{timestamp}.csv"
def start_or_continue_file(self): """Start a new CSV file or continue with existing one.""" new_file_path = self.get_current_file_path()
# If we already have this file open, keep using it if self.current_file == new_file_path and self.csv_file and not self.csv_file.closed: return self.current_file
# Close any existing file self.close_current_file()
self.current_file = new_file_path file_exists = self.current_file.exists()
# Open file in append mode if it exists, write mode if new mode = 'a' if file_exists else 'w' self.csv_file = open(self.current_file, mode, newline='', encoding='utf-8') self.current_writer = csv.DictWriter(self.csv_file, fieldnames=self.headers, extrasaction='ignore')
# Write header only for new files if not file_exists: self.current_writer.writeheader()
return self.current_file
def save_update(self, update): """Save BGP update to CSV file.""" try: # Create a new file if needed if not self.current_file or not self.current_writer: self.start_or_continue_file()
# Extract prefixes and next_hop from announcements prefix = 'N/A' next_hop = 'N/A' if update.get('announcements'): announcement = update['announcements'][0] # Take first announcement prefix = ', '.join(announcement.get('prefixes', [])) next_hop = announcement.get('next_hop', 'N/A')
# Format withdrawals withdrawals = ', '.join(update.get('withdrawals', []))
# Format the data for CSV row = { 'timestamp': datetime.fromtimestamp(update['timestamp']).strftime('%Y-%m-%d %H:%M:%S'), 'prefix': prefix, 'peer': update.get('peer', 'N/A'), 'peer_asn': update.get('peer_asn', 'N/A'), 'path': ' > '.join(str(asn) for asn in update.get('path', [])), 'next_hop': next_hop, 'type': update.get('type', 'N/A'), 'origin': update.get('origin', 'N/A'), 'aggregator': update.get('aggregator', 'N/A'), 'community': str(update.get('community', [])), 'withdrawals': withdrawals, 'host': update.get('host', 'N/A'), 'id': update.get('id', 'N/A'), 'raw': json.dumps(update) }
# Write to CSV self.current_writer.writerow(row) self.csv_file.flush() # Ensure data is written to disk return True
except Exception as e: logging.error(f"Error saving update: {str(e)}") return False
def close_current_file(self): """Close the current CSV file.""" if self.csv_file and not self.csv_file.closed: self.csv_file.flush() os.fsync(self.csv_file.fileno()) # Ensure all data is written to disk self.csv_file.close() self.csv_file = None self.current_writer = None
def get_saved_files(self): """Get list of all saved data files.""" return sorted(self.base_dir.glob("bgp_updates_*.csv"))
def read_updates(self, file_path): """Read updates from a saved file.""" return pd.read_csv(file_path)
def check_filtered_updates(self, file_path, as_numbers): """Check updates in a file that match AS number filters.""" df = self.read_updates(file_path) if 'path' not in df.columns: return pd.DataFrame()
# Convert path to string and filter rows where path contains any of the AS numbers df['path'] = df['path'].astype(str) mask = df['path'].apply(lambda x: any(str(asn) in x.split(' > ') for asn in as_numbers)) return df[mask]
def __del__(self): """Cleanup on deletion.""" self.close_current_file()
